                # location) holds none of its clusters; not a permission gap.
                if exc.error.get("reason") == "LOCATION_POLICY_VIOLATED":
                    continue
                if exc.error.get("reason") == "SERVICE_DISABLED":
                    raise  # project-wide; every other region would repeat it
                failures.append(exc)
        if failures:
            raise failures[0]
